import "./SecondAdoptionInfoContainer.css";
const SecondAdoptionInfoContainer = () => {
  return (
    <div className="adopt-info-section-between">
      <div className="second-section">
        <div>
          <h3 className="adopt-info-title-between">How It Works</h3>
          <p className="adopt-info-paragraph-between">
            Rafeeq is dedicated to helping animals find their forever homes.
            <br />
            Our platform allows individuals to post their pets for adoption
            while also showcasing animals directly under Rafeeq’s care.
            <br />
            Each adoption involves a small fee, which helps cover care and
            medical expenses.
            <br />
            Fees vary based on the type of animal and their age, ensuring a fair
            process for all adopters.
            <br />
          </p>
        </div>
      </div>
    </div>
  );
};

export default SecondAdoptionInfoContainer;
